import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchBE: [CaseTemplate] = [funeralRingsTaken, sergeantTicketCash, clerkDismissalFees, motherFalseAlibi, witnessPaidToLeave, jurorParkingLot, evidenceLogDetective, teenFakeKidnapReport, rivalHouseSwatting, nineOneOneFlood, dragDeputyStop, taserFootChase, kidsInBackChase, interstateTruckDeath, streetRaceBystander, crosswalkHitRun, minivanChildDeath, sixthDwiRollover, revokedFamilyCrash, fleetBrakeWarning, scaffoldNoHarness, dogsKillChild, kennelFireAnimals, warehouseInventoryBurn, neighborCarGarageBurn, stillAndGenerators, scrapYardCopper, poisonedNeighborDogs, puppyMillCrates, bearCubVideos, barEjectedShooting, rentTrailerShooting, clubAmbushKilling, poolHallDebtKilling, houseDriveByShots, backpackGunSchool, fathersGunShooting]

    static let funeralRingsTaken = SmallCases.make(
        key: "story.funeralRingsTaken",
        category: .property,
        headlines: ["Funeral Home Worker Took Rings From the Deceased", "Families Notice Missing Jewelry"],
        law: "felonyLarceny",
        threshold: 8,
        spec: "Took and carried away property of {V} and others valued at $9,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Five families found jewelry missing from the deceased after viewings. {D}, a funeral home worker, sold gold at a shop on {DATE}. {DL} says the gold was from {D.his} own family.",
        state: [E(.document, 3, "Gold Shop Records", "{D} sold gold on five dates."), E(.document, 3, "Family Reports", "Rings missing after prep."), E(.video, 2, "Prep Room Camera", "{D} alone with remains.")],
        defense: [E(.statement, 1, "Family Gold", "{DL} says the gold was {D.his} own.")],
        role: "Funeral director",
        exam: [.direct("What did five families report to you?", "\"After viewings at our funeral home, five families found jewelry missing from their loved ones. Rings were gone after the bodies had been prepared.\""), .direct("How was {DL} connected?", "\"{D} worked for us. The prep room camera shows {DL} alone with the remains, and a gold shop's records show {DL} selling gold on five separate dates.\""), .direct("Why do those dates matter?", "\"Each sale came after a family's viewing. The timing lines up with when the jewelry disappeared, and that's why we went to the gold shop.\""), .direct("How did you first learn that jewelry was missing?", "\"A family called the morning after a viewing to say their relative's wedding ring was not on the hand. We checked the prep log, and the ring had been listed on arrival.\""), .direct("How many families reported this and over what period?", "\"Five over about two months. Each described a ring or a pendant that was on the deceased at intake and gone at the viewing.\""), .direct("What does the prep room camera show?", "\"{D.He} alone with remains in each of the five cases, working at the table for a stretch while no one else is in the room.\""), .cross("{DL} says the gold was from {D.his} own family, doesn't {D.he}?", "\"People do sell old family gold. I can't say that none of it was {DL}'s.\""), .cross("Was {DL} the only person in the prep room?", "\"Not always. Other staff come and go. But the camera shows {DL} alone on the occasions that mattered.\""), .cross("Did anyone see {DL} take a ring?", "\"No. No one saw it. I have the camera, the family reports, and the shop records.\""), .cross("Are there blind spots in that camera?", "\"Yes. It covers the table but not the supply cabinet or the corner by the door. I cannot say what happens out of its view.\""), .cross("Did anyone else have access to the remains?", "\"Embalmers and a driver also handle remains. {D.He} was the only one alone on all five dates.\"")],
        defenseRole: "Gold buyer",
        defenseExam: [.direct("Do you buy gold at your shop?", "\"Yes. I weigh and buy all sorts of scrap gold. I record each seller's ID.\""), .direct("Did {DL} sell old pieces?", "\"A mix. Some old chains and a few other items. Nothing that looked unusual to me.\""), .direct("What did {DL} say about them?", "\"That they were family pieces. That's a common thing for sellers to say.\""), .direct("How long have you bought gold at your shop?", "\"Eleven years. I weigh scrap, test the karat, and record the seller's ID and the item type.\""), .direct("What can you tell about {D}'s sales?", "\"{D} sold chains, small rings, and bits of broken jewelry, five times over two months. Each sale was documented with ID.\""), .direct("Did the weights match any particular missing items?", "\"I never compared them with the families' reports. Deputies may have, but I did not.\""), .cross("Did {DL} sell class rings?", "\"Yes. A few. That's not rare. People sell class rings all the time.\""), .cross("Did you check where the gold came from?", "\"No. We check ID, not the source. I can't tell the history of a ring.\""), .cross("How many times did {DL} come in?", "\"Several times. I'd have to check my records for the exact count.\""), .cross("Did the defendant say where each piece came from?", "\"In general, family pieces. {D.He} did not give me names or details for each item.\""), .cross("Do you ever check if gold has been reported stolen?", "\"I check a database for reported thefts. Nothing from {D.his} sales showed up there.\"")],
        theory: ("{D} took jewelry from the dead.", "Family gold."),
        allocution: "\"I'm so ashamed.\"",
        truths: ("The gold weights match the missing rings.", "{DL} inherited old jewelry that year."),
        defendant: [.direct("Where did the gold you sold come from?", "\"It was my own family's gold, old pieces I'd had for a long time. I sold some when money got tight.\""), .direct("Did you take rings from the deceased?", "\"No. Never. I treated every person in our care with respect, and I would never take anything from them.\""), .direct("Why were you alone in the prep room?", "\"That's part of my job. I prepare remains, and I'm often alone. It doesn't mean I took anything.\""), .direct("How long have you worked at the funeral home?", "\"Six years. I prepare remains, dress the deceased, and help the director at services.\""), .direct("What do you do with a ring or jewelry at intake?", "\"We photograph it and note it on the form. Families decide whether it stays or is returned, and I follow the form.\""), .direct("What was the gold you sold?", "\"Old pieces from my own family: a few chains, a broken bracelet, and a couple of rings. I took them to a shop when I needed cash.\""), .cross("You sold gold five times, didn't you?", "\"Yes. I sold when I needed money. I never thought anyone would connect it to the families.\""), .cross("Five families lost jewelry, didn't they?", "\"That's what I hear. I'm sorry for them. I didn't take it.\""), .cross("Class rings are in the gold you sold, aren't they?", "\"Some, yes. They were in my family. I didn't know I'd be questioned about it.\""), .cross("Five sales matching five viewings. Isn't that a remarkable coincidence?", "\"It looks that way. But I sold on the days I needed money, and the timing could just be a pattern of when bills came due.\""), .cross("Some of the gold was a class ring. Whose class ring was it?", "\"My relative's. I did not copy any inscription, and I did not take it from anyone at work.\"")],
        openings: ("Five families found jewelry missing from the deceased after viewings. {D}, a funeral home worker, was alone with the remains on the prep room camera, and sold gold at a shop on five dates. The State will show the records and the video.", "The defense will point you to family gold sold openly under {D.his} own name at a shop, and no witness who saw {D} take anything from anyone."),
        closings: ("Five families, five viewings, five gold sales. {D} was alone with the remains, and the jewelry disappeared. Trust in a funeral home depends on this not happening.", "Gold sold under a real name is not proof it was taken from the dead. The State has not proved {D} stole from a single family."),
        timeline: [(-60, "First family notices."), (0, "Month 2: the fifth family."), (0, "Month 2: the shop records."), (1, "{DL} is suspended.")],
        identified: "Gold shop records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "It was my mother's wedding ring.",
        doctrines: ["burdenOfProof"])

    static let sergeantTicketCash = SmallCases.make(
        key: "story.sergeantTicketCash",
        category: .whiteCollar,
        headlines: ["Police Sergeant Took Cash to Drop Tickets", "Envelope Passed at Diner"],
        law: "bribery",
        threshold: 8,
        spec: "Corruptly accepted a thing of value as a public official, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, a police sergeant, took $400 on {DATE} from a motorist to void four tickets. An SBI recording captured the exchange. {DL} says it was repayment of a loan.",
        state: [E(.video, 3, "SBI Recording", "An envelope passes to {D}."), E(.document, 3, "Ticket Records", "Four tickets voided."), E(.statement, 2, "Motorist", "'He said it would go away.'")],
        defense: [E(.statement, 1, "Loan", "{DL} says it was a loan repayment.")],
        role: "SBI agent",
        exam: [.direct("What did your recording capture?", "\"An envelope passing to {D}, a police sergeant, from a motorist. It held $400, and the motorist wanted four tickets to go away.\""), .direct("What happened to the tickets?", "\"Four tickets were voided, all on the same day. The ticket records show {DL} voiding them.\""), .direct("What did the motorist tell you?", "\"That {D.he} said it would go away. The motorist described the whole arrangement to us after the exchange.\""), .direct("How did the investigation start?", "\"A motorist came to us after a sergeant offered to void tickets for cash. We set up a controlled meeting with a hidden recorder.\""), .direct("What happened with the tickets afterward?", "\"Records show the four tickets were voided about an hour later under {D.his} login. No reason was entered in the system.\""), .direct("What did the sergeant say to the motorist during the recorded meeting?", "\"That the tickets would go away for $400. There was no talk of a loan, and the recording captured the envelope being handed over.\""), .cross("{D} says the $400 was repayment of a loan, doesn't {D.he}?", "\"Yes. {D.He} says the motorist owed {D.him} money. A prior note shows a loan between them.\""), .cross("Was the note old?", "\"It was dated well before the tickets. I will not deny it exists.\""), .cross("Does a sergeant have authority to void tickets?", "\"In some cases a supervisor can. That is part of why timing and the money matter here.\""), .cross("Did the defendant mention a loan on the recording?", "\"Not in the words I heard. The talk was about taking care of the tickets.\""), .cross("How old is the loan note you reviewed?", "\"It is dated several months before the tickets. I confirmed the date but not that any repayment was due.\"")],
        defenseRole: "Records clerk",
        defenseExam: [.direct("Who voided the four tickets in your records?", "\"{D} did, under {D.his} login. The records show it was done in a single session on the same day.\""), .direct("On what authority did {D} void them?", "\"As a sergeant. A sergeant has authority to void tickets in certain circumstances, such as errors or officer requests.\""), .direct("Did that authority cover these four tickets?", "\"It could have, depending on the reason. I do not know the reason {DF} gave in the system.\""), .direct("What do you do in the records office?", "\"I enter citations, process voids and dismissals, and keep the audit trail of who changed what.\""), .direct("What does the system show for these four tickets?", "\"A void entry under {D.his} login at about 1 p.m. with no reason typed in. Voids normally need a short note.\""), .direct("What are the rules on who may void a citation?", "\"A supervisor can do it for clear errors. A reason is expected, and if the motorist knows the supervisor, it should go to someone else.\""), .cross("Did the defendant write a reason when voiding the tickets?", "\"I do not recall seeing one. I would have to check the file, and I do not think there was a clear reason.\""), .cross("Are sergeants supposed to void tickets for people they know?", "\"No. That would be a conflict. They are supposed to follow procedure and note a reason.\""), .cross("Did anyone approve the voids?", "\"Not that I know of. {D.He} acted on {D.his} own authority.\""), .cross("Did the defendant contact you about the voids?", "\"No. The first I heard was in the audit after the sting.\""), .cross("Were any other voids by the defendant flagged?", "\"Not that I saw. These four were the ones that stood out.\"")],
        theory: ("{D} took a bribe.", "A loan repayment."),
        allocution: "\"I'm ashamed.\"",
        truths: ("{DL} voided the tickets the same day.", "A prior note shows a loan to the motorist."),
        defendant: [.direct("Did you take a bribe?", "\"No. I took $400 as repayment of a loan. The motorist borrowed that money from me.\""), .direct("Did you void the four tickets?", "\"Yes, I voided them. I believed they were written in error, and I had the authority to void them.\""), .direct("What about the note about the loan?", "\"It is old. It shows I lent the motorist money months before any of the tickets.\""), .direct("How long have you been a sergeant?", "\"Fourteen years. I supervise patrol shifts and review traffic citations when drivers dispute them.\""), .direct("What was your history with the motorist?", "\"I knew the motorist from the neighborhood. I lent money a few months earlier when it was needed, and we wrote a short note.\""), .direct("Why did you void the four tickets?", "\"I reviewed them and found errors in the paperwork. I decided they should be dismissed, and that was within my authority.\""), .cross("You took an envelope of cash and voided tickets the same day, didn't you?", "\"Yes. The timing looks bad. But the money was repayment of the loan, not payment for the tickets.\""), .cross("The motorist told agents you said it would go away. Did you?", "\"I said something about taking care of the problem. I did not mean it the way it sounds.\""), .cross("A sergeant who takes cash from a motorist with tickets. How is that not corruption?", "\"I see how it looks. I did not sell a favor. I was repaid.\""), .cross("You took an envelope while voiding tickets for the same person. Why not wait for the repayment?", "\"The motorist offered to pay that day. I should have kept the two matters apart, and I did not.\""), .cross("You said 'it will go away.' What did that refer to?", "\"The debt, in my mind. I can see how it sounds like the tickets, and I regret my wording.\"")],
        openings: ("An SBI recording captured a motorist passing {D}, a police sergeant, an envelope containing $400. The same day, four of the motorist's tickets were voided under {D}'s authority.", "The defense witnesses will explain that the $400 repaid a loan documented in an old note and that {D} voided tickets believing they were written in error."),
        closings: ("Cash in an envelope, four tickets voided the same day, and a motorist who heard that it would go away. That is a bribe taken by a sergeant who knew better.", "A documented loan, a repayment, and a sergeant with authority over tickets. The State must prove the money bought the voids, and coincidence is not corruption."),
        timeline: [(-7, "The tickets issue."), (0, "Noon: the envelope."), (0, "1 p.m.: the voids."), (30, "The sting reviews.")],
        identified: "A recording.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let clerkDismissalFees = SmallCases.make(
        key: "story.clerkDismissalFees",
        category: .whiteCollar,
        headlines: ["Court Clerk Took Cash to Dismiss Traffic Tickets", "Dismissals Without a Judge"],
        law: "bribery",
        threshold: 8,
        spec: "Corruptly accepted a thing of value as a public official, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, a deputy clerk, took $1,100 across seven tickets on {DATE} and marked them dismissed without a judge's order. {DL} says people were paying fines. The first dismissal came three months before the audit. The files show seven tickets dismissed without orders, and a motorist says {D.he} paid the clerk in cash.",
        state: [E(.document, 3, "Case Files", "Seven tickets dismissed without orders."), E(.digital, 3, "Deposit Slips", "$1,100 into {D}'s account."), E(.statement, 2, "Motorist", "'I paid the clerk in cash.'")],
        defense: [E(.statement, 1, "Fines", "{DL} says the cash was fines.")],
        role: "Clerk of court",
        exam: [.direct("What did your audit of the clerk's office find?", "\"Seven tickets were dismissed without a judge's order. The first dismissal came about three months before the audit.\""), .direct("How is {DL} tied to those files?", "\"{D}, a deputy clerk, processed them. Deposit slips show $1,100 going into {D.his} account across the seven tickets.\""), .direct("What did a motorist say?", "\"A motorist said, 'I paid the clerk in cash.' That payment never reached our books.\""), .direct("How did you discover the dismissals?", "\"During an audit, we noticed seven tickets marked dismissed with no judge's signature. The entries came from one login.\""), .direct("What did you learn about the cash?", "\"Deposit slips show $1,100 going into an account in {D.his} name over about three months, matching the amounts of the seven fines.\""), .direct("What is the proper procedure when someone pays a fine?", "\"We take the payment, issue a receipt, and deposit into the court account. A dismissal needs a judge's order.\""), .cross("{DL} says the cash was fines, doesn't {D.he}?", "\"Fines are paid to us, not into a deputy's personal account.\""), .cross("Do deputy clerks take payments at the window?", "\"Sometimes, yes. But they must be receipted and deposited in the court's account.\""), .cross("Did you see {DL} take cash?", "\"No. I reviewed the files and the slips. I didn't see the transactions.\""), .cross("Did {D} ever explain the deposits?", "\"{DL} said the cash was fines and that {DL} intended to deposit them but fell behind.\""), .cross("Were the receipts issued for those seven tickets?", "\"I found no receipts. That is part of why the audit flagged them.\"")],
        defenseRole: "Deputy clerk",
        defenseExam: [.direct("Do you work with {DL}?", "\"Yes. I'm a deputy clerk too. I see how {D} handles the window.\""), .direct("Did {DL} take payments?", "\"Sometimes. When people pay fines, any of us at the window may take them.\""), .direct("What kind of payments?", "\"Usually checks or money orders. Fines are posted to the account.\""), .direct("How is the clerk's office organized?", "\"Four of us take turns at the window. We share the same drawer and the same register for checks and money orders.\""), .direct("What kind of payments does the window usually take?", "\"Checks and money orders, with an occasional cash payment. We write receipts for all of them.\""), .direct("What can you tell the jury about {D}'s work?", "\"{D.He} was quick and friendly at the window. I never saw anything in {D.his} handling of money that raised concern.\""), .cross("Did {DL} take cash?", "\"Not usually. Most payments were not cash. Cash is unusual for us.\""), .cross("Did {DL} dismiss tickets on {D.his} own?", "\"I wouldn't think so. Dismissals need a judge. I don't know about these.\""), .cross("Did you see {DL} deposit money elsewhere?", "\"No. I only saw the window. I have no knowledge of accounts.\""), .cross("Who authorizes a dismissal?", "\"A judge. A deputy clerk cannot dismiss a ticket without an order.\""), .cross("Did you see any of the seven tickets pass through the window?", "\"No. I do not remember any of them, and I was not at the window for those dates.\"")],
        theory: ("{D} took bribes.", "Fines."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} paid a car note with the cash.", "{DL} sometimes took payments at the window."),
        defendant: [.direct("Why were tickets dismissed without orders?", "\"I thought I was authorized to close them once people paid. I didn't realize it needed a judge's order.\""), .direct("Where did the $1,100 go?", "\"Into my account. I know it should have gone to the court. I made a bad choice and mishandled it.\""), .direct("Did you plan to keep the fines?", "\"I meant to deposit them. I got behind, and I didn't catch up. I was in over my head.\""), .direct("How long have you been a deputy clerk?", "\"Nine years. I take payments, file motions, and answer questions at the counter.\""), .direct("How did you end up taking cash?", "\"People came to the window with cash, and I accepted it. I meant to deposit the money in the court's account that afternoon.\""), .direct("Why did you mark the tickets dismissed?", "\"To clear them from the system once the fines were paid. I thought it was routine, and I never asked a judge.\""), .cross("Seven tickets were dismissed, weren't they?", "\"Yes. I marked them dismissed after taking the money. I know that was wrong.\""), .cross("You deposited the cash in your own account, didn't you?", "\"Yes. I should have used the court's account. I don't have a good explanation.\""), .cross("No judge signed any of them, did one?", "\"No. I never asked a judge. That is on me.\""), .cross("You put the money in your own account. Is that routine?", "\"No. I used my account because I needed the money for a car note, and I told myself I would put it back.\""), .cross("Seven tickets, no judge, no receipts. How is that not theft?", "\"It is. I misused the court's money, and I am ashamed of it.\"")],
        openings: ("{D}, a deputy clerk, took $1,100 across seven tickets and marked them dismissed with no judge's order. Deposit slips show the money in {D}'s account. The State will present the clerk of court and a motorist.", "Jurors will also see a clerk who sometimes took payments at the window and got behind, not a clerk who set out to steal from the court."),
        closings: ("Seven dismissed tickets, no judge's order, and $1,100 in cash in {D}'s own account. A clerk who takes fines and keeps them breaks the public's trust.", "{D} took payments at the window as clerks do and mishandled the paperwork. The State has not proved {D} meant to keep the court's money."),
        timeline: [(-90, "The first dismissal."), (0, "Month 3: the audit."), (0, "Month 3: the deposits."), (1, "{DL} is suspended.")],
        identified: "Case files.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let motherFalseAlibi = SmallCases.make(
        key: "story.motherFalseAlibi",
        category: .publicOrder,
        headlines: ["Mother Lied Under Oath to Give Son an Alibi", "Phone Records Contradict Testimony"],
        law: "perjury",
        threshold: 6,
        spec: "Willfully made a false statement under oath in a judicial proceeding, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} testified on {DATE} that her son was home all night. His phone showed him across town. {DL} says the phone was left at a friend's.",
        state: [E(.document, 3, "Transcript", "'He was home all night.'"), E(.digital, 3, "Phone Records", "The son's phone across town."), E(.statement, 2, "Neighbor", "The son's car was gone.")],
        defense: [E(.statement, 1, "Phone Left", "{DL} says the phone was left elsewhere.")],
        role: "Court reporter",
        exam: [.direct("What did {D} say in court?", "\"In the transcript, {D} testified that {D.his} child was home all night. I recorded every word of the testimony.\""), .direct("What did the phone records later show?", "\"The child's phone was across town that night. The location records put the phone far from the home.\""), .direct("What did a neighbor say?", "\"That the child's car was gone that night. The neighbor said it was not in the driveway.\""), .direct("What was your role at the trial where the defendant testified?", "\"I was the court reporter. I transcribed every word, including {D.his} testimony on the afternoon of the second day.\""), .direct("What exactly did the defendant say about the child's whereabouts?", "\"{D.He} swore the child was home all night, twice, when asked by counsel and again on follow-up.\""), .direct("How did the phone records come into the case?", "\"The prosecution subpoenaed location data for the child's phone. It showed the phone across town from about 9 p.m. until 2 a.m.\""), .cross("Do you know whether the child was with the phone?", "\"No. I only know where the phone was. I cannot say who was holding it.\""), .cross("{D} says the phone was left at a friend's, doesn't {D.he}?", "\"Yes, that is what {D.he} says. A friend confirms the phone was left at the friend's house.\""), .cross("Did the defendant seem to believe the testimony?", "\"I cannot judge that. I recorded the words and did not evaluate the witness.\""), .cross("Did the defendant hesitate or look at any notes?", "\"No. {D.He} spoke steadily and did not refer to anything. I do not read demeanor, but I did not note any pauses.\""), .cross("Did anyone challenge the defendant about the car?", "\"Yes, on cross. The neighbor's account of the missing car was put to {DL}, and {DL} said {D.he} did not know.\"")],
        defenseRole: "Son's friend",
        defenseExam: [.direct("Where was the phone that night?", "\"At my house. The phone was left at my place, and I did not return it until the next day.\""), .direct("Was the child with the phone?", "\"I am unsure. I think the child left earlier and left the phone behind. I did not see the child leave.\""), .direct("How did the phone end up at your house?", "\"The child came by in the evening and forgot it on a table. I picked it up later and kept it for the night.\""), .direct("How do you know {D}'s child?", "\"We have been friends since school. I see {D}'s child often and have been to their house many times.\""), .direct("What happened with the phone that night?", "\"My friend stopped by around eight and left the phone on a table. I did not see it until the next morning.\""), .direct("What did you do when you found it?", "\"I texted to say I had it and would return it. I did not think it mattered at the time.\""), .cross("Do you know where the child was after leaving your house?", "\"No. I do not. I did not ask, and the child did not tell me.\""), .cross("Did you tell the defendant the phone was at your house?", "\"Not that night. I told {DF} later. I should have said it sooner.\""), .cross("Did you see the child's car that night?", "\"I did not look. I was inside most of the night.\""), .cross("Did you tell the defendant about the phone before the trial?", "\"No. I only said something afterward. I should have spoken up earlier.\""), .cross("Where did your friend go after leaving the phone?", "\"I do not know. I did not ask, and my friend did not say.\"")],
        theory: ("{D} lied for her son.", "A mistaken belief."),
        allocution: "\"I couldn't let them take him.\"",
        truths: ("{DL} knew the car was gone.", "The son's friend confirms the phone was left."),
        defendant: [.direct("Did you lie under oath?", "\"No. I did not lie. I believed my child was home all night, and I said what I believed.\""), .direct("Why did you believe that?", "\"The child told me so, and I was asleep. I had no reason to think otherwise.\""), .direct("Was the car gone that night?", "\"Maybe. I did not check the driveway. I would not have known.\""), .direct("How would you describe your relationship with your child?", "\"Close. We talk often, and my child usually tells me where they are going. I trust my child.\""), .direct("What happened the night in question?", "\"I went to bed early and slept through. My child said goodnight and that they would be home. I believed it.\""), .direct("How did you learn about the phone records?", "\"From the prosecutor, after I had testified. I was stunned and asked a friend what it could mean.\""), .cross("The phone was across town, wasn't it?", "\"Yes. But the phone was left at a friend's. A friend confirms that.\""), .cross("You knew the car was gone, didn't you?", "\"I did not know. I may have suspected, but I did not know.\""), .cross("You are a parent protecting a child, aren't you?", "\"I am. But I did not lie to protect anyone. I said what I believed.\""), .cross("A parent who sleeps through the night cannot say the child was home. Why did you say so?", "\"I believed it. I trusted my child, and I did not think I was saying anything false.\""), .cross("The neighbor says the car was gone. Did you look at the driveway before testifying?", "\"No. I did not think to check. I should have been more careful before I swore to anything.\"")],
        openings: ("{D} testified under oath that {D.his} child was home all night. Phone records later put the child's phone across town, and a neighbor saw the child's car gone from the driveway.", "The defense case is that {D} honestly believed the testimony, that the phone was left at a friend's house, and that {D} did not know the car was gone."),
        closings: ("A sworn statement that the child was home, a phone across town, and a car gone from the driveway. A parent who swears to what the evidence refutes has lied under oath.", "A phone left at a friend's house and a parent who believed the child was home. The State must prove {D} knew the testimony was false, and a parent's belief is not a lie."),
        timeline: [(0, "Trial day: the oath."), (0, "Trial day: the testimony."), (7, "The records."), (30, "{DL} is charged.")],
        identified: "Phone records.",
        mood: .sympathetic,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .female])

    static let witnessPaidToLeave = SmallCases.make(
        key: "story.witnessPaidToLeave",
        category: .violent,
        headlines: ["Defendant's Friend Paid Witness to Leave Town Before Trial", "Cash App Trail"],
        law: "witnessIntimidation",
        threshold: 7,
        spec: "Attempted to deter a witness from testifying by offering a thing of value, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Days before a trial, {D} sent $800 to {V}, a witness, and told {V.him} to 'be out of town.' {DL} says it was a loan. The trial had been set three days earlier. The messages told {V} to 'be out of town Friday,' and {V} reported it two days later.",
        state: [E(.digital, 3, "Payment App", "$800 to {V}."), E(.digital, 3, "Messages", "'Be out of town Friday.'"), E(.statement, 2, "Witness", "'He said stay away.'")],
        defense: [E(.statement, 1, "Loan", "{DL} says it was a loan.")],
        role: "Witness",
        exam: [.direct("What did {D} send you?", "\"$800 through a payment app, three days after the trial was set. It came with a message that said to be out of town Friday.\""), .direct("What did the defendant tell you?", "\"Stay away. I understood that I should not come to testify. The message said 'Be out of town Friday.'\""), .direct("What did you do?", "\"I reported it two days later. I was frightened, and I did not know whether to keep the money.\""), .direct("How did you know the defendant?", "\"We had been friends for years. We had also lent each other money a few times, and I had borrowed once before.\""), .direct("What did the message say?", "\"A text read, 'Be out of town Friday.' It arrived with the $800 payment two days before the trial, and I knew {D} was the defendant.\""), .direct("What did you do about the money?", "\"I held onto it, did not spend any, and showed the messages to a lawyer. Two days later I called the prosecutor.\""), .cross("{D} says the $800 was a loan, doesn't {D.he}?", "\"Yes. {D.He} says we had a prior loan. I know there was one, but it was small and old.\""), .cross("Was the prior loan partly repaid?", "\"Partly, yes. I do not deny that.\""), .cross("The message could have been about a vacation, couldn't it?", "\"It could. But it was sent days before trial, and I was a witness. I read it differently.\""), .cross("Did the defendant ever say why you should leave?", "\"Not in any message. The text was short, and {D.he} did not explain.\""), .cross("Were you already planning to be away that Friday?", "\"No. I had no travel plans. That is why the message caught my attention.\"")],
        defenseRole: "Mutual friend",
        defenseExam: [.direct("Was there a prior loan between {D} and the witness?", "\"Yes. {D} lent the witness money months before, and I know about it because I was there.\""), .direct("Was the loan repaid?", "\"Partly. The witness paid some back, but not all. It was an ongoing thing between them.\""), .direct("What do you think the $800 was for?", "\"I think it was a loan or part of the old arrangement. I never heard {D.him} say anything about the trial.\""), .direct("How do you know both the defendant and {V}?", "\"We are all part of the same group of friends. I have known them both for years and was around when money changed hands.\""), .direct("What did you know about the prior loan?", "\"{D.He} lent {V} money a few months earlier. {V} paid back part but not all, and they talked about it as an ongoing thing.\""), .direct("What did the defendant say about the trip?", "\"That it was an invitation for a fishing weekend. It had been planned for a while and was not tied to anything else.\""), .cross("Did you know about the trial date?", "\"Yes. Everyone in our circle knew it was coming up. It was set about three days earlier.\""), .cross("Did you see the message that said to be out of town?", "\"I heard about it.\""), .cross("Did the defendant ask you to talk to the witness?", "\"No. I did not talk to the witness for {DF}.\""), .cross("Did the defendant ever tell you to talk to {V} about the trial?", "\"No. {DF} never asked me to say anything to {V}.\""), .cross("Were you in the group chat when the message was sent?", "\"No. I heard about it later from others.\"")],
        theory: ("{D} bought a witness's absence.", "A loan."),
        allocution: "\"I'm sorry.\"",
        truths: ("The payment came two days before trial.", "{DL} and {V} had a prior loan."),
        defendant: [.direct("Did you pay the witness to leave?", "\"No. I did not pay for anyone to leave. The $800 was a loan to a friend who needed it.\""), .direct("Was there a prior loan?", "\"Yes. We had an older loan, and the new money was part of that arrangement.\""), .direct("What did your message about Friday mean?", "\"I meant a vacation. I mentioned being out of town because I had a trip planned, and I invited the witness.\""), .direct("How long have you known {V}?", "\"About eight years. {V} and I helped each other through hard times, including a small loan I made earlier.\""), .direct("Why did you send $800?", "\"{V} asked for help with a bill. I sent the money as a loan and added a note about a trip we had talked about.\""), .direct("What trip were you thinking about?", "\"A weekend fishing trip we had planned for months. I wanted {V} to come, and the invitation came up in the same text.\""), .cross("You sent money days before a trial to the witness, didn't you?", "\"Yes. The timing is a coincidence. I did not think about the trial.\""), .cross("The message said 'be out of town Friday.' Isn't that telling the witness to stay away?", "\"It was meant as a vacation invitation. I know how it reads now.\""), .cross("You are on trial, and the witness would testify against you, wouldn't the witness?", "\"Yes. That is why I was careful. I did not want to look like I was interfering, and I failed.\""), .cross("You are on trial and {V} was a witness. Why would you send money days before testimony?", "\"It looks bad, I know. I did not think about it at the time. I was trying to help a friend.\""), .cross("The text told {V} to be out of town on the day of the trial. Did you know that was the date?", "\"I knew trial was coming, but I did not connect it with that Friday.\"")],
        openings: ("Three days after a trial was set, {D} sent {V}, a witness, $800 and a message telling {V} to 'be out of town Friday.' {V} reported it two days later.", "Weigh the defense proof, which will show that the $800 was a loan tied to an older debt and that the message was about a vacation, with no threat in it."),
        closings: ("$800 sent to a witness three days after the trial date, with a message to be out of town. That is how a witness is paid to disappear.", "An old loan, a new loan, and a message about a trip. The State must prove {D} meant to keep {V} from testifying, and a coincidence of timing is not enough."),
        timeline: [(-3, "The trial is set."), (0, "The payment."), (2, "The witness reports."), (3, "{DL} is arrested.")],
        identified: "Payment records.",
        mood: .wantsConviction,
        impact: "I was afraid to testify.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let jurorParkingLot = SmallCases.make(
        key: "story.jurorParkingLot",
        category: .publicOrder,
        headlines: ["Man Approaches Juror in Parking Lot Seeking to Talk About Case", "Juror Reports Contact"],
        law: "obstruction",
        threshold: 6,
        spec: "Willfully obstructed justice by attempting to communicate with a juror, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} approached {V}, a juror, in a parking lot on {DATE} and said the defendant was 'a good man.' {DL} says {D.he} did not know {V.he} was a juror. {D} approached {V} at about 8:35 a.m., five minutes after arriving. {V} is on the jury roster and reported the approach by 9 a.m.",
        state: [E(.statement, 3, "Juror", "'He said the defendant was a good man.'"), E(.video, 2, "Lot Camera", "{D} approaches {V}."), E(.document, 3, "Jury Roster", "{V} was on the panel.")],
        defense: [E(.statement, 1, "Unaware", "{DL} says {D.he} did not know.")],
        role: "Juror",
        exam: [.direct("What happened in the parking lot on {DATE}?", "\"At about 8:35 a.m., five minutes after I arrived, {D} approached me and said the defendant was a good person.\""), .direct("Were you on the jury?", "\"Yes. I was on the panel, and the jury roster shows it. I had been summoned for that trial.\""), .direct("What did you do?", "\"I reported it right away. By 9 a.m. I'd told court staff what happened. I didn't want anything to affect my duty.\""), .direct("Where were you and what was the situation?", "\"In the courthouse parking lot at about 8:30 a.m., walking toward the entrance with my juror badge pinned to my jacket.\""), .direct("What did {D} say to you?", "\"{DL} came up, said good morning, and added that the defendant was a good person. Then {DL} walked away.\""), .direct("What did you do?", "\"I went directly to the court officer, told the officer exactly what was said, and was brought to the bailiff before the day began.\""), .cross("{DL} says {D.he} did not know you were a juror, doesn't {D.he}?", "\"I was wearing my juror information, but it's possible {DL} didn't notice.\""), .cross("Was your badge clearly visible?", "\"It was partly visible. I can't promise it was readable from where {D.he} stood.\""), .cross("Did {DL} say anything else?", "\"No. {D.He} said it and walked away. It was brief. There was no threat.\""), .cross("Did the defendant mention the case by name?", "\"No. {D.He} did not say the name. Only that the defendant was a good person.\""), .cross("How big is the badge?", "\"About the size of a business card, hanging from a lanyard. It was visible, but I would not call it large.\"")],
        defenseRole: "Parking attendant",
        defenseExam: [.direct("Do you work at the courthouse lot?", "\"Yes. I'm the parking attendant. I see everyone coming in.\""), .direct("Was the badge visible?", "\"Partly. Jurors wear a badge, but it's small. It can be hidden by a coat.\""), .direct("Did you see the exchange?", "\"I saw two people talking briefly. I didn't hear what was said.\""), .direct("How long have you worked the courthouse lot?", "\"Nine years. I direct cars and watch the entrance, and I know many of the regulars.\""), .direct("How can you tell a juror from a visitor?", "\"Jurors wear a small badge on a lanyard. People coming for other business often carry papers or no badge at all.\""), .direct("What did you see between {D} and {V}?", "\"{D} walked up, spoke a short sentence, and walked away. Neither of them seemed upset.\""), .cross("Was it clear {V} was a juror?", "\"Maybe, if you looked. I can't say a stranger would notice.\""), .cross("Did {DL} approach {V}?", "\"It looked that way. I saw {DF} walk up. It wasn't hurried.\""), .cross("Did you stop them?", "\"No. It happened quickly. I didn't know what was being said.\""), .cross("Could you read the badge from where you stood?", "\"No. I was a few car lengths away and could not read it.\""), .cross("Did you stop to ask what was said?", "\"No. It took only a few seconds and I did not think it was anything.\"")],
        theory: ("{D} tried to influence a juror.", "Unaware."),
        allocution: "\"I'm sorry.\"",
        truths: ("{V} wore a juror badge.", "{DL} greeted {V} by chance."),
        defendant: [.direct("Why did you speak to {V}?", "\"I greeted someone in the lot and made a comment about my relative. I didn't know the person was a juror.\""), .direct("Did you know about the badge?", "\"No. I didn't see it. If I had seen it, I wouldn't have said anything.\""), .direct("Why were you at the courthouse that morning?", "\"I came to support a relative who was the defendant. I walked from the lot toward the main door and saw someone who looked familiar.\""), .direct("What did you say to {V}?", "\"A friendly hello and that the defendant is a good person. I was making conversation, thinking I was speaking to another visitor.\""), .direct("What did you do when you learned who {V} was?", "\"I was horrified. I told deputies exactly what I had said and that I had not recognized the juror.\""), .direct("What did you do after the juror stopped answering you?", "\"I realized I had said too much and walked inside. I told a deputy what had happened because I did not want any trouble.\""), .cross("You said the defendant was a good person, didn't you?", "\"Yes. I said it. I didn't realize who I was talking to.\""), .cross("It was 8:35 in the morning at the courthouse, wasn't it?", "\"Yes. I was heading in. I wasn't thinking about the jury.\""), .cross("You approached {V} on purpose, didn't you?", "\"I greeted {V}. I didn't know {V.he} was a juror. It was a mistake.\""), .cross("You said something favorable about the defendant to a stranger. Why?", "\"Because I was nervous and talking to everyone about my relative. I should have kept quiet.\""), .cross("The badge was on {V}'s jacket. How did you miss it?", "\"I was looking at {V}'s face, not the badge, and I was thinking about my relative.\"")],
        openings: ("{D} approached {V}, a juror, in the courthouse lot at about 8:35 a.m. and said the defendant was a good person. {V} reported it by 9. The State will show the lot camera and the jury roster.", "The defense will present a person who greeted a stranger in a parking lot, did not see a badge, and never knew {V} was a juror."),
        closings: ("A juror in the lot, a comment about the defendant, and {D}'s approach on camera. Jurors must be protected from this kind of contact.", "{D} did not know {V} was a juror and spoke casually. The State has not proved {D} meant to influence a juror."),
        timeline: [(0, "8:30 a.m.: arrival."), (0, "8:35 a.m.: the approach."), (0, "9 a.m.: the report."), (1, "{DL} is arrested.")],
        identified: "A juror.",
        mood: .divided,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let evidenceLogDetective = SmallCases.make(
        key: "story.evidenceLogDetective",
        category: .publicOrder,
        headlines: ["Detective Altered Evidence Log to Hide Missing Drugs", "Seal Numbers Do Not Match"],
        law: "obstruction",
        threshold: 7,
        spec: "Willfully obstructed justice by altering evidence records, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Seal numbers on an evidence bag did not match the log on {DATE}. Thirty grams were missing. {D}, a detective, signed the log. {DL} says it was a clerical error.",
        state: [E(.document, 3, "Evidence Log", "Seal numbers altered."), E(.forensic, 3, "Weight Check", "Thirty grams short."), E(.statement, 2, "Property Clerk", "'{D} signed it out.'")],
        defense: [E(.statement, 1, "Clerical", "{DL} says it was a clerical error.")],
        role: "Property clerk",
        exam: [.direct("What did you find in the evidence log on {DATE}?", "\"The seal numbers on an evidence bag did not match the log. The numbers had been altered.\""), .direct("What did the weight check show?", "\"Thirty grams short. A bag that should have held a certain weight was light.\""), .direct("Who signed the log?", "\"{D}, a detective. I recorded that {D.he} signed it out. I have the sign-out in my records.\""), .direct("What is your job and how does evidence get logged?", "\"I am the property clerk. Every bag is weighed, sealed with a numbered tape, and logged by me when it comes in and when it leaves.\""), .direct("What went wrong with this bag?", "\"The tape on the bag showed one number, and the log showed a different number in a darker pen. The weight at audit was thirty grams below the intake weight.\""), .direct("What does the log say about who signed the item out?", "\"{D.his} signature is on the sign-out line the day before the audit. The seal number next to it is the one that was altered.\""), .cross("{DL} says it was a clerical error, doesn't {D.he}?", "\"Clerical errors happen. But an altered seal number and missing weight go beyond a typo.\""), .cross("How many people can sign out evidence?", "\"Several detectives. {D.He} wasn't the only one with access. But {D.his} name was on that bag.\""), .cross("Did you see {DL} alter the numbers?", "\"No. I only know what the log shows. I wasn't watching when the bag was handled.\""), .cross("Was the log page rewritten?", "\"The page shows some rewriting. It was a busy day with many entries, so I cannot say who wrote what.\""), .cross("Did {D} have any prior problems with evidence handling?", "\"None that I know of. {D.He} had a clean record on my watch.\"")],
        defenseRole: "Fellow detective",
        defenseExam: [.direct("Do you work with {DL}?", "\"Yes. I'm a fellow detective. I know how the evidence room works.\""), .direct("Was it busy that day?", "\"Very. We had a lot of items moving. The log pages get crowded.\""), .direct("Do mistakes happen?", "\"Yes. Handwriting gets sloppy. A seal number can be copied wrong.\""), .direct("How long have you worked in the unit?", "\"Twelve years. I use the evidence room often and have seen how the log is kept.\""), .direct("What is the room like on a busy day?", "\"Crowded and loud. Detectives line up, the clerk is writing fast, and log pages get filled with different pens.\""), .direct("What do you know about {D}'s work habits?", "\"{D} is careful with cases, but not always neat on paperwork. I have seen {D.his} handwriting trip up more than once.\""), .cross("Could an altered number be a mistake?", "\"Possibly. It depends on how it was altered. I haven't studied it.\""), .cross("Was it altered here?", "\"Unknown. I haven't seen the page closely. I can't say.\""), .cross("Did you see {DL} handle the bag?", "\"No. I wasn't present. I only know the setting.\""), .cross("Did you see the entry that day?", "\"No. I was not in the room when {D.he} signed.\""), .cross("Do clerical errors usually involve seal numbers?", "\"Sometimes. But a changed seal number is not routine, and a short weight is what makes this different.\"")],
        theory: ("{D} altered a log.", "A clerical error."),
        allocution: "\"I regret it.\"",
        truths: ("{DL} had a gambling debt.", "The log pages were rewritten on a busy day."),
        defendant: [.direct("Did you alter the seal numbers?", "\"No. I never changed any numbers. If a number was wrong, it was a clerical mistake.\""), .direct("How busy was the evidence room that day?", "\"Very busy. We were signing items in and out constantly. Mistakes can happen in that setting.\""), .direct("Did you take thirty grams?", "\"No. I didn't take any evidence. I'd never put my career and my cases at risk.\""), .direct("What is your role in the department?", "\"I am a detective in the property crimes unit. I sign evidence out for case work and back in when I am finished.\""), .direct("What happened that day in the evidence room?", "\"The line was long and the clerk was swamped. I signed the log in a hurry and walked out with a bag for a lab appointment.\""), .direct("How did you react when told thirty grams were short?", "\"I was stunned. I asked to look at the log and offered to be interviewed and to take any test they wanted.\""), .cross("You signed the log, didn't you?", "\"Yes. I signed it. That's my job. I don't remember writing a wrong number.\""), .cross("The bag was thirty grams light, wasn't it?", "\"That's what the weight check says. I don't know why. I didn't take it.\""), .cross("A detective knows how to seal a bag, doesn't {D.he}?", "\"Of course. That's why I think it was a clerical slip, not tampering.\""), .cross("You have a gambling debt. Isn't that a motive?", "\"I do have a debt and I have been open about it. That does not mean I took evidence.\""), .cross("If the numbers were altered, who altered them?", "\"I do not know. It could have been me by mistake, someone else rewriting a page, or a copying error.\"")],
        openings: ("Seal numbers on an evidence bag did not match the log, and thirty grams were missing. {D}, a detective, signed the log. The State will present the property clerk and the weight check.", "Jurors will also see a busy evidence room, a log full of hurried entries, and a detective who says it was a clerical error. Listen closely to the witnesses."),
        closings: ("Altered seal numbers, a bag that came back thirty grams light, and a detective's name on the sign-out line. Evidence is supposed to be sacred, and this log failed that test.", "A rushed day in a crowded evidence room produced a messy log, and a messy log is not a theft. The State has not shown that {D} took anything or changed a single number on purpose."),
        timeline: [(-14, "The bag is sealed."), (0, "The audit."), (0, "The weight check."), (1, "{DL} is placed on leave.")],
        identified: "An evidence log.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["chainOfCustody"])

    static let teenFakeKidnapReport = SmallCases.make(
        key: "story.teenFakeKidnapReport",
        category: .publicOrder,
        headlines: ["Teen Reports Own Kidnapping to Avoid Trouble at Home", "Search Involves 80 Volunteers"],
        law: "falseReport",
        threshold: 6,
        spec: "Gave a false report of a crime to a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} told deputies on {DATE} that {D.he} was forced into a van. 80 volunteers searched for hours. {D} later said {D.he} had skipped school and invented it. {DL} says {D.he} was scared.",
        state: [E(.video, 3, "Street Camera", "{D} walks alone."), E(.statement, 3, "Deputy", "'He gave a false story.'"), E(.document, 2, "Search Log", "80 volunteers, six hours.")],
        defense: [E(.statement, 1, "Scared", "{DL} says {D.he} was scared of punishment.")],
        role: "Deputy",
        exam: [.direct("What did {D} tell you?", "\"That {D} had been forced into a van. {D.He} gave that story to me and repeated it twice.\""), .direct("What did the street camera show?", "\"It shows {DL} walking alone. No van, and no one forcing {DL} anywhere.\""), .direct("How big was the search?", "\"Eighty volunteers searched for six hours. The search log shows it. Deputies spent all that time on a false report.\""), .direct("What was the first report you received?", "\"At about 9 a.m., {DL} called from a pay phone near a school and said {D.he} had been dragged into a van by two people. {DL} described the van and the direction it went.\""), .direct("What did deputies do after the report?", "\"We broadcast the description, asked for volunteers, and started grid searches. Eighty volunteers and several deputies walked fields, roads, and wooded lots until mid-afternoon.\""), .direct("What did the street camera add?", "\"It showed {DL} walking alone along a sidewalk at the time {DL} claimed to be in the van. No van was visible in the frame or anywhere on the block.\""), .cross("How long before the defendant told the truth?", "\"Within hours. {D.He} confessed to deputies that the story was invented.\""), .cross("How old is the defendant?", "\"A teen. {D.He} was a student who had skipped school that day.\""), .cross("Did the defendant seem scared when confessing?", "\"Yes. {DL} was upset and cried. I could see {DL} was frightened.\""), .cross("Did the defendant change the story during questioning?", "\"Not at first. {DL} repeated it to me and to a second deputy. By about 3 p.m., after we showed the video, {DL} admitted it was made up.\""), .cross("Did you consider that {D} might truly have been afraid of something?", "\"Yes. {DL} was crying and said school and home pressure made {DL} panic. I took that seriously, but the false report cost us a lot.\"")],
        defenseRole: "School counselor",
        defenseExam: [.direct("Was {D} under pressure at school?", "\"Yes. {D} had been under a lot of pressure for weeks, with grades and family issues.\""), .direct("Was the defendant truthful that day?", "\"Not that day. {D.He} told a lie about being taken. I do not defend that.\""), .direct("Why do you think the defendant invented it?", "\"Fear. {D.He} had skipped school and did not know how to explain. It spiraled.\""), .direct("What is your role at the school?", "\"I am a counselor. I meet with students about grades, stress, and family issues, and I know {D.him} from several sessions.\""), .direct("What did you notice about the defendant in the weeks before?", "\"{D.He} was anxious and withdrawn. Grades were slipping, and {D.he} told me about a lot of pressure at home.\""), .direct("How did the defendant act when you met after the confession?", "\"Tearful and ashamed. {D.He} apologized repeatedly and asked what could be done to make it right.\""), .cross("Did {D} tell you the truth afterward?", "\"Yes. {D.He} admitted it was invented. That was within hours.\""), .cross("Did the defendant understand what the lie would cause?", "\"I do not think so. {D.He} did not think about the search or the volunteers.\""), .cross("Did you counsel the defendant before the incident?", "\"I had talked to {D.him} about stress. Nothing about this.\""), .cross("Did the defendant tell you about the van story before the confession?", "\"No. I first heard about it after the report went out. I had no contact with {D.him} that morning.\""), .cross("Does stress excuse a false report?", "\"No. It helps explain it, but {D.he} is still responsible for what happened.\"")],
        theory: ("{D} lied about a kidnapping.", "A scared teen."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} repeated the story twice.", "{DL} confessed within hours."),
        defendant: [.direct("Did you lie to deputies?", "\"Yes, I did. I said I was forced into a van, and it was not true.\""), .direct("Why did you lie?", "\"I was scared. I had skipped school, and I did not want to get in trouble.\""), .direct("Did you tell the lie more than once?", "\"Yes. I told it twice. It got out of hand, and I did not know how to stop.\""), .direct("What was going on in your life that week?", "\"I was behind in two classes and afraid my parent would find out I had skipped. I had missed a test and lost track of what I owed.\""), .direct("How did you come up with the story?", "\"I was walking and panicking about how to explain myself. The van story popped into my head as the first thing I could say.\""), .direct("What did you feel when you learned how many people were searching?", "\"Sick. I knew then that I could not take it back without getting in trouble, and I felt trapped until I finally told the truth.\""), .cross("Eighty volunteers searched for six hours because of your lie, didn't they?", "\"Yes. I feel terrible about it. I did not think it would turn into that.\""), .cross("You confessed only after hours of searching, didn't you?", "\"I confessed within hours. I should have confessed right away.\""), .cross("You told the same lie twice. Isn't that deliberate?", "\"I was frightened. I kept going with it. I know that is no excuse.\""), .cross("You told it to two different deputies. Isn't that planning?", "\"It was fear, not planning. I stuck to it because I was afraid, and each repetition made it harder to stop.\""), .cross("How many hours passed before you told the truth?", "\"About six. I should have told the first deputy. I let eighty people look for a crime that never happened.\"")],
        openings: ("A teen told deputies on {DATE} that {D} had been forced into a van. Eighty volunteers searched for six hours, and a street camera shows {D} walking alone. {D} later admitted inventing the story.", "By the end of this trial, the proof will show that {D} was a frightened teen who had skipped school, panicked, confessed within hours, and never meant to cause a search."),
        closings: ("A false report of a kidnapping, repeated twice, eighty volunteers searching for six hours, and a camera that shows {D} alone. The lie had a cost.", "A scared student who skipped school, told a lie that snowballed, and confessed within hours. This calls for understanding, not the harshest penalty."),
        timeline: [(0, "9 a.m.: the report."), (0, "9 a.m. to 3 p.m.: the search."), (0, "3 p.m.: the confession."), (1, "{DL} is charged.")],
        identified: "A street camera.",
        mood: .sympathetic,
        doctrines: ["lesserIncluded"],
        genders: ["D": .male])

    static let rivalHouseSwatting = SmallCases.make(
