        exam: [.direct("What did the caller report?", "\"A gunman inside {V}'s home. We surrounded the house and ordered a child outside at gunpoint.\""), .direct("Where did the call trace to?", "\"To {D}'s phone. {D.He} is a classmate of the family's child.\""), .direct("What did the messages show?", "\"It showed {DL} bragging about it in a group chat. The messages were posted after the response.\""), .direct("What call came in and when?", "\"At about 8 p.m. a caller said an armed person was inside {V}'s home and threatening the family. The dispatcher sent four units.\""), .direct("What did you do on arrival?", "\"We set up a perimeter, took cover behind cars, and used a loudspeaker. A child came out the front door and was ordered to put hands up at gunpoint.\""), .direct("What did you find inside?", "\"No gunman, no weapon, and a frightened family. The call was false, and the family was shaken by what we had put them through.\""), .cross("{D} says a friend used {D.his} phone, doesn't {D.he}?", "\"Yes. The friend has admitted using the phone. I know that.\""), .cross("Was the defendant at the scene?", "\"No. {D.He} was not at the scene. The call came from elsewhere.\""), .cross("Was the group chat message a joke?", "\"It could be read as a joke. It was in poor taste in any case.\""), .cross("How did you trace the call?", "\"Dispatch pulled the number and carrier records. It came back to {D.his} phone, which had been used for a short call at 8 p.m.\""), .cross("Did you speak with the friend who used the phone?", "\"Yes. The friend admitted borrowing the phone and making the call. The friend did not name a reason.\"")],
        defenseRole: "Friend",
