        role: "Dispatcher",
        exam: [.direct("What did you see in the call log?", "\"Sixty calls from {D} on one day about neighbors. The call log shows them all from the same number.\""), .direct("What did you hear on those calls?", "\"The same voice and the same complaint each time. It was about neighbors.\""), .direct("What was the effect on your center?", "\"A cardiac call was delayed by ninety seconds while we handled the flood. That is a long time in a heart emergency.\""), .direct("What did your dispatch screen show that day?", "\"A repeating call from the same number every few minutes. By the end of the day, there were sixty calls, all from {D.his} phone.\""), .direct("What did {D} say on the calls?", "\"Complaints about neighbors: noise, parked cars, people on the porch. The dispatcher notes list the same voice and nearly the same words.\""), .direct("How did the flood affect a real emergency?", "\"A cardiac call came in at the same time and our lines were tied up. The caller waited ninety seconds longer than normal for an answer.\""), .cross("{D} says the reports were real, doesn't {D.he}?", "\"Yes. {D.He} says {D.he} was reporting crimes. Some of the complaints were real.\""), .cross("Was there a real crime next door that week?", "\"Yes. A break-in occurred next door that week. I know that.\""), .cross("Was {D} warned?", "\"Yes. {D.He} was warned the day before about misusing the line.\""), .cross("Did all sixty calls describe crimes?", "\"Some described things that might have been crimes. Many were about noise or parking, which are not emergencies.\""), .cross("Was that same break-in reported through 911 that week?", "\"Yes. A real break-in occurred next door earlier in the week and was handled normally.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Was there a crime in the neighborhood?", "\"Once, a break-in next door. It was real, and the police came.\""), .direct("Did {D} call sixty times that day?", "\"No. I do not think so. I did not hear that many calls.\""), .direct("Did the defendant report real problems?", "\"Some were real. {D} worried a lot about the neighborhood.\""), .direct("How long have you lived next to the defendant?", "\"Seven years. We wave and talk on the porch, and I know {D.he} tends to worry about the neighborhood.\""), .direct("What happened with the break-in next door?", "\"Someone pried the back door of a house on our street. Deputies came and took a report, and all of us were shaken.\""), .direct("How did the defendant react?", "\"{D.He} was nervous for days, checked every window, and called me several times to ask if I heard anything.\""), .cross("Did you hear the defendant making the calls?", "\"No. I did not hear them.\""), .cross("Were most of the complaints about noise?", "\"Many were about small things. I would not call them crimes.\""), .cross("Do you get along with {D}?", "\"We are neighbors. I am not close to {D.him}, and I do not want to speak for {D.him}.\""), .cross("Did you hear the defendant call 911 that day?", "\"No. I was at work. I only learned about the sixty calls later.\""), .cross("Did the defendant report problems that turned out to be real?", "\"Some, yes. Others were things like parked cars and music, which were annoying but not criminal.\"")],
        theory: ("{D} jammed 911.", "Reporting crimes."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} was warned the day before.", "A real break-in occurred next door that week."),
        defendant: [.direct("Did you try to jam up 911?", "\"No. I did not mean to jam it. I was reporting what I thought were crimes.\""), .direct("Were your reports real?", "\"Yes. I saw things that worried me, and I thought deputies needed to know.\""), .direct("Were you warned about calling?", "\"Yes. I was warned the day before. I did not think the warning applied to real crimes.\""), .direct("What was going on in your neighborhood?", "\"Strange people were hanging around next door, and a break-in earlier in the week left me on edge. I felt unsafe.\""), .direct("Why did you keep calling?", "\"Each time something happened, I called again. I did not think about how it looked. I wanted somebody to come.\""), .direct("What did you do when you learned a heart patient was delayed?", "\"I felt awful. I called the center the next day to apologize and told them I would stop.\""), .cross("Sixty calls in one day. Isn't that too many?", "\"It is a lot. I was upset, and I kept calling.\""), .cross("A heart patient waited an extra ninety seconds. Do you understand that?", "\"I do not like hearing that. I did not know. I feel awful about it.\""), .cross("A real break-in did happen next door, but sixty calls?", "\"Yes. I was worried about more. I overdid it.\""), .cross("You were warned the day before to stop misusing 911. Why did you keep calling?", "\"I did not think I was misusing it. I thought I was reporting real things, and I was upset.\""), .cross("Sixty calls in one day leaves no room for a real emergency. Do you see that?", "\"I see it now. I should have called the non-emergency line, and I am sorry.\"")],
        openings: ("{D} called 911 sixty times in a single day about neighbors, tying up the line so that a cardiac call was delayed ninety seconds. The dispatcher says it was the same voice and the same complaint.", "The defense witnesses will explain that {D} was reporting what {D} believed were real crimes, that a real break-in occurred next door, and that {D} never meant to block anyone."),
        closings: ("Sixty calls, the same voice, a warning the day before, and a cardiac call delayed ninety seconds. Misusing the emergency line has a cost.", "A worried neighbor who overdid it after a real break-in next door. The State must prove {D} meant to disrupt the line, and worry is not intent."),
        timeline: [(-1, "The warning."), (0, "Sixty calls."), (0, "A cardiac call delayed."), (1, "{DL} is arrested.")],
        identified: "A call log.",
        mood: .divided,
        doctrines: ["relevance"],
        genders: ["D": .male])

    static let dragDeputyStop = SmallCases.make(
