        defense: [E(.statement, 1, "Fear", "{DL} says {D.he} feared for {D.his} safety.")],
        role: "Deputy",
        exam: [.direct("What happened at the stop on {DATE}?", "\"{D} refused to produce a license, claiming sovereign status. Then {D.he} drove off while I was holding the door.\""), .direct("What do the records show about {DL}'s license?", "\"No license had been issued to {D.him}. That's in the records, along with the body camera of the stop.\""), .direct("What was the reason for the stop?", "\"A taillight out on a sedan at about 1 p.m. I approached, introduced myself, and asked for a license and registration.\""), .direct("What did {D} say?", "\"{D.He} said the laws did not apply to {D.him} and refused to hand anything over. I repeated that I needed a license and held the door while we spoke.\""), .direct("What happened at 1:12?", "\"{D.He} put the car in gear and drove off while my arm was inside the door frame. I was dragged about thirty feet before I let go and rolled.\""), .direct("What did you do after the vehicle stopped?", "\"I got to my feet and checked myself for injuries. I called for backup, and {D.he} was taken into custody without any further resistance.\""), .cross("{DL} says {D.he} feared for {D.his} safety, doesn't {D.he}?", "\"I was in uniform and I was trying to conduct a lawful stop.\""), .cross("How quickly did {DL} stop?", "\"Within seconds, I'd say. It felt long to me, but it wasn't a long drive.\""), .cross("Were you seriously hurt?", "\"No. Scrapes and soreness. It could have been much worse, and that's what bothers me.\""), .cross("Did the defendant accelerate hard?", "\"It was a quick start. I would call it a lurch more than a launch, and {D.he} slowed within a few seconds.\""), .cross("Did the defendant resist arrest after stopping?", "\"No. {D.He} stopped, put the car in park, and put hands out. {D.He} was compliant after that.\"")],
        defenseRole: "Passenger",
        defenseExam: [.direct("Were you in the car?", "\"Yes, I was a passenger. I saw the whole stop.\""), .direct("Did {DL} intend to hurt the deputy?", "\"No. {D} panicked. {D.He} drove off in fear and not with any plan.\""), .direct("What did {DL} do after?", "\"Stopped fast. I'd say within a few seconds. {D.He} said sorry.\""), .direct("How do you know {D}?", "\"I am a friend. I was in the passenger seat the afternoon of the stop and watched the whole thing.\""), .direct("What did the defendant say to the deputy?", "\"That {DF} did not have to give ID. The deputy kept asking, and {DF}'s voice got higher and shakier.\""), .direct("What did you notice when the car started to move?", "\"It lurched as {D.he} hit the gas. I yelled to stop, and {D.he} slammed the brakes within a couple of seconds.\""), .cross("Did {DL} stop quickly?", "\"Yes. It was only a few seconds. Then {D.he} stopped and put the car in park.\""), .cross("Did {DL} speed away?", "\"Not fast. It was more like a lurch. I felt the car jump.\""), .cross("Did you tell {DL} to stop?", "\"I did. I yelled. I was frightened too.\""), .cross("Did the defendant know the deputy had a hand on the door?", "\"I do not think so. The deputy was behind the window line, and {DF} was looking ahead.\""), .cross("Did you tell the defendant to comply earlier?", "\"Yes. I said to hand over the license, but {D.he} refused.\"")],
        theory: ("{D} dragged a deputy.", "Fear."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} said the law did not apply.", "{DL} stopped within seconds."),
        defendant: [.direct("Why did you drive away?", "\"I panicked. I was scared of what would happen. I didn't mean to hurt anyone.\""), .direct("Why did you refuse to give a license?", "\"I believed I didn't need one. I was wrong, and I was caught up in a belief I'd picked up.\""), .direct("Did you know the deputy was holding the door?", "\"Not at first. I felt a tug, and I stopped as soon as I realized. I never meant to drag anyone.\""), .direct("Why did you believe the law did not apply to you?", "\"I had read material online about being a sovereign citizen and thought I did not need a license. It was a foolish belief.\""), .direct("What were you thinking when the deputy stood at the door?", "\"That I was being trapped. I felt crowded and scared, and I did not understand how serious the situation was.\""), .direct("How did you stop?", "\"As soon as I felt the tug and heard the shout, I hit the brake. I know it was only a few seconds.\""), .cross("You drove off with the deputy at the car, didn't you?", "\"Yes. It was a terrible decision. I'm very sorry.\""), .cross("You had no license, did you?", "\"No. I'd never had one issued. I told the deputy I didn't need it. That was wrong.\""), .cross("The body camera shows you driving away, doesn't it?", "\"Yes. It shows the whole thing. I'm not going to argue with it.\""), .cross("You were told to produce a license and refused. Why not just comply?", "\"Because I held on to a wrong idea. I know now that I should have complied.\""), .cross("You drove with a deputy's arm in the door. Isn't that reckless?", "\"Yes. I did not see the arm. That is no excuse, and I am so sorry.\"")],
        openings: ("{D} refused to produce a license, claimed sovereign status, and drove off while a deputy held the door, dragging the deputy thirty feet. The State will show the body camera and the deputy's injuries.", "Jurors will also see a frightened driver who panicked, stopped within seconds, and never planned to hurt anyone. Listen closely to the witnesses."),
        closings: ("A deputy standing at the car door, a driver who would not hand over a license and chose to drive away, and thirty feet of dragging captured on body camera. That is not an accident; that is an assault.", "{D} was frightened, made a bad decision, and stopped within seconds. The State has not proved that {D} meant to harm the deputy, only that {D} panicked in a moment of confusion."),
        timeline: [(0, "1 p.m.: the stop."), (0, "1:10 p.m.: the refusal."), (0, "1:12 p.m.: the drive."), (0, "1:13 p.m.: arrest.")],
        identified: "A body camera.",
        aggravating: ["The victim was a law enforcement officer performing official duties"],
        mood: .divided,
        doctrines: ["lesserIncluded"],
        genders: ["D": .male])

