        defenseExam: [.direct("Do you treat children at a hospital?", "\"Yes. I'm a pediatric nurse. I see many children with fevers.\""), .direct("Did the child have a fever?", "\"Earlier, according to the history I was given. It's the kind of thing that worries parents.\""), .direct("Is that a reason to rush?", "\"Some parents panic over fevers. It's understandable, though not always necessary.\""), .direct("What is your work as a pediatric nurse?", "\"I assess children in an urgent care unit, including those with fevers and headaches. Parents often come in scared.\""), .direct("What can you tell the jury about the child's condition?", "\"The chart shows a fever earlier that day. By the time I saw the child, the temperature was normal and there were no warning signs.\""), .direct("How do fevers typically get handled?", "\"Usually with fluids and medicine at home. Most do not call for a rush, but a sore neck can be a warning sign, so a worried parent has some reason.\""), .cross("Was it an emergency by then?", "\"Not by then. The child seemed fine by the time I saw anything.\""), .cross("Would you drive 120 for a fever?", "\"No. That's not advisable. It's dangerous.\""), .cross("Did you see the child that day?", "\"Only afterward. I can't say what happened in the car.\""), .cross("Would a parent be justified in driving 120 mph?", "\"No. It put the children at much greater risk than the fever did.\""), .cross("Did you speak with {D} after the crash?", "\"Briefly. {D} was shaken and kept apologizing. I did not hear the full story.\"")],
        theory: ("{D} led a chase with kids aboard.", "A rush to care."),
        allocution: "\"I put them in danger.\"",
        truths: ("{DL} passed an exit for the hospital.", "One child had a fever earlier."),
        defendant: [.direct("Why were you driving so fast?", "\"One of my children had a fever and I was rushing to a hospital. I panicked and didn't stop.\""), .direct("Why didn't you pull over for the deputies?", "\"I was afraid of the delay. I thought they could escort me, but I didn't know how to stop.\""), .direct("Were the children in danger?", "\"I thought a hospital was the safest place. I see now that driving 120 put them at risk.\""), .direct("What was happening with your child that evening?", "\"My child ran a fever earlier and was complaining of a headache and a sore neck. I panicked and decided to drive to the hospital.\""), .direct("Why did you not stop for the deputies?", "\"I thought stopping would cost me time. I was in a panic and could not think. I kept my foot down.\""), .direct("How did you feel when the car went off the road?", "\"Terrified for the children. I climbed out as soon as I could and checked both of them before the deputy arrived.\""), .cross("120 miles an hour with children in the back, isn't that reckless?", "\"Yes. I know it was. I'm ashamed. I wasn't thinking.\""), .cross("You never went to a hospital, did you?", "\"No. I crashed before. There was no emergency visit.\""), .cross("The fever was earlier, wasn't it?", "\"It was earlier that day. It was still on my mind. I overreacted.\""), .cross("You never reached a hospital. Why not?", "\"I crashed before I got there. I was driving far too fast and not thinking about the road.\""), .cross("If it was truly urgent, why not call 911?", "\"I should have. I was not thinking clearly, and I made the wrong choice.\"")],
        openings: ("{D} fled deputies at 120 mph for nine miles with two children in the back seat. The car ended in a ditch, and the hospital has no record of an emergency visit. The State will show the dash camera and the deputy.", "The defense will point you to a frightened parent whose child had a fever, who panicked, and who never meant to endanger the children. Listen closely to the witnesses."),
        closings: ("120 miles an hour, nine miles, two children in the back, and a ditch. There was no emergency visit. {D} put those children at grave risk.", "A fever, a panic, and a wrong decision. {D} loved those children and was trying to protect them. The State has not proved a deliberate disregard for their safety."),
        timeline: [(0, "8 p.m.: the lights."), (0, "8:02 p.m.: the chase."), (0, "8:11 p.m.: the ditch."), (0, "8:30 p.m.: arrest.")],
        identified: "A dash camera.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        doctrines: ["necessity"])

    static let interstateTruckDeath = SmallCases.make(
