        defenseExam: [.direct("Was the timing of the light off?", "\"A fault was logged in the system that week. It affected how long the yellow lasted.\""), .direct("Was the timing off on that night?", "\"Unclear. We do not have a clear record of that exact night.\""), .direct("How could a fault affect a driver?", "\"A shorter yellow can catch a driver before they can stop. It can turn a yellow into a red fast.\""), .direct("What is your role with the city?", "\"I am a traffic engineer. I design signals, set timing, and review incidents and maintenance logs for intersections like that one.\""), .direct("What did the log show for that intersection?", "\"A fault was entered earlier that week for the yellow timing. A technician reset it, and I did not see a second entry.\""), .direct("How do you determine a yellow interval?", "\"From the posted speed and the approach grade. At 35 miles an hour, it should be about three seconds.\""), .cross("Was the camera showing red when {D} entered?", "\"I did not review the camera myself. I understand it showed red.\""), .cross("Did you inspect the light after the crash?", "\"Yes. I found a fault in the timing. I do not know how long it had been there.\""), .cross("Would a .14 driver have stopped anyway?", "\"I cannot say. That is not an engineering question.\""), .cross("Did anyone test the signal after the crash?", "\"Yes. We timed it and found it within range. I cannot say what it was doing that night.\""), .cross("Would a sober driver stop for a three-second yellow?", "\"In most cases, yes. A yellow that short can catch someone only if they are speeding or distracted.\"")],
        theory: ("{D} ran a red drunk.", "A yellow light."),
        allocution: "\"I'll never forgive myself.\"",
        truths: ("{DL} left a bar twenty minutes earlier.", "The light timing was off that week."),
        defendant: [.direct("Had you been drinking before the crash?", "\"Yes, I had. I was at a bar earlier that night, and I left about twenty minutes before the crash.\""), .direct("Was the light yellow or red when you entered?", "\"Yellow. I believed I could make it through, and I saw yellow. I did not think I was running a red.\""), .direct("What about the light's timing?", "\"It was off, I think. The yellow seemed short to me, and I heard afterward that a fault was logged.\""), .direct("How much had you had to drink?", "\"A few drinks over a couple of hours. I did not feel impaired, and I thought I was fine to drive the short distance home.\""), .direct("What do you remember about the light?", "\"It was yellow when I approached. I thought I could make it, and I did not hit the brake.\""), .direct("What did you do after the crash?", "\"I got out and ran to the minivan. I saw the child and froze. I told the trooper I had been drinking and did everything asked.\""), .cross("You were at a .14, weren't you?", "\"Yes, I was. I know that. I should not have been driving at all that night.\""), .cross("A seven-year-old died. Do you accept responsibility for that?", "\"I do. I think about that child every single day, and I will for the rest of my life.\""), .cross("The camera shows red. Is the camera wrong?", "\"I do not know. I only know what I saw, and I saw yellow. I cannot say more.\""), .cross("The camera shows the light red. Do you doubt it?", "\"I cannot say what the camera shows over what I saw. I know I should not have been driving.\""), .cross("At .14 you were nearly twice the limit. Do you see how that affects judgment?", "\"I do now. A seven-year-old is dead, and I will live with that.\"")],
