        role: "Highway Patrol trooper",
        exam: [.direct("What did you find at the crash?", "\"A rolled truck, and {D} beside it. I arrived at 1:20 a.m., and the crash had come at about 1 a.m.\""), .direct("What did you notice about {D}?", "\"{D.He} had the keys. A breath test at 2 a.m. read .16.\""), .direct("What do the defendant's records show?", "\"Six prior DWI convictions. The certified records are in evidence.\""), .direct("How did the crash come to your attention?", "\"At about 1 a.m. a passing driver reported a truck on its roof beside the highway. I arrived at 1:20 and found the cab crushed and {D.he} standing nearby.\""), .direct("What did you find on the scene?", "\"Fresh scrape marks, a rolled truck, an empty seat belt buckle, and no one else present. {D.He} had the keys in a front pocket.\""), .direct("How was the defendant's breath test done?", "\"At about 2 a.m. at the station, after rights were read. The reading was .16 on a certified device.\""), .cross("{D} says someone else drove, doesn't {D.he}?", "\"Yes. {DL} said a friend drove and left the scene.\""), .cross("Did you see anyone else at the scene?", "\"No. {D.He} was alone when I arrived.\""), .cross("Was the defendant's phone in the truck?", "\"Yes. The phone was in the truck. That is part of the evidence.\""), .cross("Did you see the defendant behind the wheel?", "\"No. I arrived after the crash. {D.He} was outside the truck and no one else was in view.\""), .cross("Did you look for another person?", "\"I checked the area with a flashlight and called for a K-9. We found nothing, but we could not search far in the dark.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Were you in the truck earlier that night?", "\"Yes. I rode with {D} earlier. We went out together, and I was in the truck for part of the night.\""), .direct("Who drove the truck at the time of the crash?", "\"I will not say. I do not want to name anyone. I know that does not help.\""), .direct("Did you leave the scene?", "\"I did not see the crash. I was not there when it happened.\""), .direct("How long have you known {D}?", "\"Ten years. We hang out at gatherings and share rides home when we have both been drinking.\""), .direct("What did you see that evening?", "\"{DF} was drinking early, and then we decided someone else should drive. We got in the truck together with the other person at the wheel.\""), .direct("Where did you get out?", "\"I did not ride the whole way. I got out at the first stop, so I do not know what happened later.\""), .cross("Why won't you say who drove?", "\"I am afraid. I do not want to be involved. That is the truth.\""), .cross("Did the defendant drive earlier that night?", "\"Yes. {D.He} drove earlier. I do not know about later.\""), .cross("Were you drinking too?", "\"Yes. I was. That is why I did not drive.\""), .cross("Who was driving when you got out?", "\"I would rather not say. I have said enough about it.\""), .cross("Did you see the crash?", "\"No. I was not there. I learned about it from a friend later that night.\"")],
        theory: ("{D} drove drunk again.", "Someone else drove."),
        allocution: "\"I'm tired of this.\"",
