        defense: [E(.statement, 1, "Deer", "{DL} says {D.he} swerved for a deer.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What did you find at the crash scene?", "\"{D}'s vehicle had crossed the center line and hit a family car head-on. Four people in the family car were injured.\""), .direct("What did you learn about {D}'s license?", "\"The DMV record shows it was revoked for a prior DWI. {D.He} should not have been driving at all that night.\""), .direct("What was the breath test result?", "\"A .09, which is over the legal limit of .08. I also found no skid marks before the center line.\""), .direct("How did the collision look when you arrived?", "\"A pickup was across the center line and the family's sedan was crushed on the driver's side. Four occupants were hurt, two seriously.\""), .direct("What did you note about the tire marks?", "\"No skid marks leading to the center line from {DL}'s side. That suggests {DL} drifted rather than braked or swerved hard.\""), .direct("What did the defendant say?", "\"That a deer ran in front and {DL} swerved. I smelled alcohol on {DL} and asked for a breath test, which read .09.\""), .cross("{D} says a deer made {D.him} swerve, doesn't {D.he}?", "\"Yes, that is what {D.he} told me. Deer tracks lined the shoulder along that stretch, I will agree.\""), .cross("If a driver swerves for a deer, would you expect skid marks?", "\"Often, though not always. A quick swerve might leave little, so I treat the lack of marks as one fact only.\""), .cross("Did you see a deer at the scene?", "\"No, I did not see a deer. I saw tracks along the shoulder, but I cannot say they were fresh.\""), .cross("Did you find any deer remains or hair?", "\"No. I found no hair, blood, or carcass at the crash site. I did see tracks on the shoulder.\""), .cross("Could a swerve leave no skid marks?", "\"Yes, if the driver steers without braking. It is possible, but I look for other signs when I rule it out.\"")],
        defenseRole: "Wildlife officer",
        defenseExam: [.direct("Are deer common along that stretch of road?", "\"Yes, very common. That road runs beside a wooded area, and we get deer crossings there every season.\""), .direct("Were there deer tracks along the shoulder that night?", "\"I saw tracks along the shoulder when I visited afterward. I cannot say whether they were from that night or earlier.\""), .direct("Can a deer cause a driver to cross a center line?", "\"Yes. Drivers swerve all the time, and a swerve at speed can carry a vehicle across the line before they recover.\""), .direct("What do you do as a wildlife officer?", "\"I manage deer populations and respond to vehicle collisions with wildlife in this county.\""), .direct("How often do deer cross that road?", "\"Every evening in season. The woods run right up to the pavement, and we log dozens of strikes a year.\""), .direct("What did you find after the crash?", "\"Fresh tracks on the shoulder and into the trees. I cannot say when they were made.\""), .cross("Do you know whether a deer was on the road that night?", "\"No. I do not know. The tracks tell me deer use the area, but not that one was there then.\""), .cross("Did you see any deer hair or a carcass at the scene?", "\"No. I did not find any hair, blood, or carcass. That would be expected only if a deer had been hit.\""), .cross("Does the presence of deer excuse driving with a revoked license?", "\"No. That is a separate matter. I only speak about the wildlife, and I do not address the license.\""), .cross("Did you see a deer or any physical evidence of one on the pavement?", "\"No. Hair, blood, or a carcass would be unusual for a near miss.\""), .cross("Could the tracks be from earlier in the day?", "\"Yes. They could be from any time that day or the day before.\"")],
        theory: ("{D} drove revoked and drunk.", "A deer."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had been drinking.", "Deer tracks lined the shoulder."),
        defendant: [.direct("Had you been drinking before the crash?", "\"I had one beer earlier that evening. I did not feel impaired, and I believed I was fine to drive.\""), .direct("What caused you to cross the center line?", "\"A deer ran into the road, and I swerved to miss it. I lost control, and the car went across the line.\""), .direct("Did you know your license was revoked?", "\"Yes, I knew. I should not have been driving, and I will not pretend otherwise to this jury.\""), .direct("What were you doing that evening?", "\"Driving to a friend's house after dinner. I had one beer with the meal and left around seven.\""), .direct("Why were you driving with a revoked license?", "\"I needed to get somewhere and told myself it was only a short drive. I knew it was wrong.\""), .direct("What exactly did you see on the road?", "\"A deer jumped out from the trees on the right. I jerked the wheel left and the truck crossed the line before I could correct.\""), .cross("You blew a .09, which is over the limit, didn't you?", "\"Yes. I know what the test said. I do not think one beer gets a person that high, but I accept the number.\""), .cross("There were no skid marks before the line. Doesn't that show you never braked?", "\"I swerved instead of braking. It happened too fast to brake, and I just turned the wheel.\""), .cross("Four people in a family car were hurt. Do you accept responsibility?", "\"I am very sorry for what happened to them. I should not have been behind the wheel at all.\""), .cross("You were driving without a license and had been drinking. Why trust you about a deer?", "\"I understand why you ask. But the tracks, the road, and the time of day all fit a deer crossing.\""), .cross("Four people are hurt. Doesn't that outweigh your explanation?", "\"It matters more than anything. I am sorry, and I accept that I should not have been on that road.\"")],
        openings: ("{D}, whose license was revoked for DWI, crossed the center line and hit a family car, injuring four people. A breath test showed .09, and there were no skid marks before the line.", "Listen for the defense evidence, which will show that deer are common on that road, that tracks lined the shoulder, and that {D} swerved to avoid one in a split second."),
        closings: ("A revoked license, a .09 reading, no skid marks, and four people hurt in a family car. {D} chose to drive, and the evidence points to impairment, not a deer.", "Deer tracks lined the shoulder and a driver swerved in a split second. The State has not proved the swerve was not for a deer, and that doubt matters."),
        timeline: [(0, "7 p.m.: the center line."), (0, "7:01 p.m.: the collision."), (0, "7:20 p.m.: medics."), (0, "8 p.m.: the test.")],
