        defense: [E(.document, 1, "Repair Order", "A repair order dated before the crash.")],
        role: "Safety investigator",
        exam: [.direct("What did your investigation find about the quarry truck?", "\"Its brakes failed on a grade. The inspection found worn linings that had failed, and {V}, a driver, died.\""), .direct("What warnings did {DL} receive?", "\"Three written brake warnings. {D}, the fleet manager, received them before the crash.\""), .direct("What did the mechanic say?", "\"The mechanic said, 'I told {D.him} twice.' The warnings were repeated verbally as well.\""), .direct("What did the brake inspection find?", "\"The linings were worn to the metal, and the drums were scored. The brakes had very little stopping power on a steep grade.\""), .direct("How did the crash happen?", "\"The quarry truck was loaded and descending a haul road when its brakes faded. The truck ran off the road and struck {V}'s vehicle.\""), .direct("What did the written warnings say?", "\"They said the brakes needed attention before the next shift, and they were sent to {DL} over several weeks. The last was a few days before the crash.\""), .cross("{DL} says repairs were scheduled, doesn't {D.he}?", "\"A repair order dated before the crash exists. I can't say the work was done in time.\""), .cross("Was the part available?", "\"I understand it was backordered. That may explain the delay, but not leaving the truck on the road.\""), .cross("Could the truck have been parked?", "\"Yes. A truck with failed brakes should not be on a grade. That was the decision that mattered.\""), .cross("Was there a repair order?", "\"Yes, dated before the crash for a brake job. I do not have proof the work began.\""), .cross("Did a mandatory daily check occur that morning?", "\"I have no record that a pre-trip brake check was done. I cannot say whether it was skipped or just not logged.\"")],
        defenseRole: "Parts clerk",
        defenseExam: [.direct("What is your role at the parts counter?", "\"I fill orders for equipment shops, including the quarry's fleet. I check inventory, place backorders, and confirm shipping dates.\""), .direct("What did {D} order, and when?", "\"A set of brake linings for that truck type, placed several weeks before the crash. I have the order slip with the date and part number.\""), .direct("What was the status of that part?", "\"On backorder because the manufacturer had a shortage. The ship date kept slipping week after week.\""), .direct("What did you tell the defendant?", "\"That the part would not arrive for about a month and that a substitute set was in stock. I explained the difference.\""), .direct("How did the defendant respond?", "\"{D} said to wait for the original. I wrote that on the order slip because it was unusual to turn down a substitute.\""), .direct("How often does a backorder like that happen?", "\"More than people think. Brake components have been hard to get lately, and we get calls about delayed parts every week.\""), .cross("Did the defendant ask whether the truck was safe to run?", "\"No. {D.He} only asked about the date the part would arrive. I did not hear any mention of safety.\""), .cross("Could the substitute part have solved the problem?", "\"Probably, as a stopgap. It would have been installed in a day.\""), .cross("Did you warn the defendant that the truck should not run on a grade?", "\"I did not. I am a parts clerk, not an inspector, and I assumed {DF} knew.\""), .cross("Are you a regular supplier for {D}?", "\"Yes, for years. I like working with {D.him}, and I am trying to be fair about what I saw.\""), .cross("Do you know whether the repair was ever scheduled?", "\"I know an order was placed. I do not know the shop's schedule.\"")],
        theory: ("{D} ignored warnings.", "Repairs were scheduled."),
