        defenseExam: [.direct("Do you hunt with {DL}?", "\"Yes. We go out often. We went out that evening.\""), .direct("Were you hunting?", "\"I thought so. That's what I understood. {D} said we were going out.\""), .direct("Where were you?", "\"Near the overlook. I stayed back. I didn't see anything.\""), .direct("How long have you hunted with {D}?", "\"Seven years. We go out most fall weekends and sit in stands near the creek.\""), .direct("What did the defendant say about that evening?", "\"That we would scout a good spot for the season. {D.He} suggested the overlook and picked a time.\""), .direct("What did you hear?", "\"One loud shot from the direction of the road. {D.He} said to wait and then we both went back to the truck.\""), .cross("Was it in season?", "\"No. It wasn't hunting season for what we had.\""), .cross("Did {DL} say what the target was?", "\"No. {D.He} just said hunting. I didn't ask.\""), .cross("Did you hear the shot?", "\"Yes. I heard it. I didn't see who fired.\""), .cross("Did you see the defendant fire a shotgun?", "\"No. I was a short distance away in the trees.\""), .cross("Did the defendant mention the club members at all?", "\"In passing. {DF} complained about some of them, but never said anything about hurting anyone.\"")],
        theory: ("{D} planned an ambush.", "A hunter."),
        allocution: "\"I can't take it back.\"",
        truths: ("{DL} had a feud with the club.", "A hunting license was valid."),
        defendant: [.direct("Why were you at the overlook?", "\"I was hunting. I'd gone out for the evening. I didn't know anyone else was there.\""), .direct("Did you shoot {V}?", "\"No. I would never shoot a person. I was hunting and heard a shot.\""), .direct("What about the texts?", "\"I didn't send them. I got a message, but I thought it was a hunting arrangement.\""), .direct("Why did you go to the overlook that evening?", "\"I wanted to scout for deer. It is a spot I have used before, and I knew the trail.\""), .direct("What did you hear while you were there?", "\"A loud shot from the road below. I was a few hundred yards off and thought someone else was hunting.\""), .direct("What did you do?", "\"I went back to my truck and drove home. I heard about the shooting later and told deputies where I had been.\""), .cross("You had a shotgun, didn't you?", "\"Yes. It's for hunting. I always carry it.\""), .cross("The shells in your truck match, don't they?", "\"They're a common type. Everyone around here uses them.\""), .cross("You were at the overlook at 6, weren't you?", "\"I was in the area. I didn't see {V}. I was hunting.\""), .cross("You have a feud with the club. Doesn't that give you a reason to ambush a member?", "\"I had words with some members. I did not plan to hurt anyone.\""), .cross("If it was a hunting trip, why was it out of season?", "\"I was scouting, not shooting. I had a gun with me out of habit.\"")],
        openings: ("{V}, a biker club member, was shot from an overlook, and texts planned the ambush. {D} was seen with a shotgun, and matching shells were in {D}'s truck. The State will present the SBI agent.", "The defense will point you to a hunter in an area where people hunt, a common shell, and no proof of who sent the texts. Listen closely to the witnesses."),
        closings: ("A text setting the time and place, a shotgun blast from the overlook, and shells in {D}'s truck that match what was found in the brush. This was an ambush, planned and carried out.", "A hunter with a common shotgun and common shells, scouting a spot near an overlook. The State has not proved who sent the text or who fired the shot that killed {V}."),
        timeline: [(-14, "The feud."), (0, "5:45 p.m.: texts."), (0, "6 p.m.: the shot."), (0, "7 p.m.: found.")],
