        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        impact: "He was our president.",
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let poolHallDebtKilling = SmallCases.make(
        key: "story.poolHallDebtKilling",
        category: .violent,
        headlines: ["Man Shot in Pool Hall Over Gambling Debt", "Camera Shows Argument at Table"],
        law: "murder2",
        threshold: 9,
        spec: "Unlawfully killed {V} with malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was shot in a pool hall on {DATE} after an argument over a $2,000 debt. {D} was filmed at the table. {DL} says {V} drew first.",
        state: [E(.video, 3, "Hall Camera", "{D} and {V} argue."), E(.forensic, 3, "Ballistics", "Casings match {D}'s pistol."), E(.statement, 2, "Patron", "'{D} pulled first.'")],
        defense: [E(.statement, 1, "Drew First", "{DL} says {V} drew first.")],
        role: "Pool hall owner",
        exam: [.direct("What happened in your pool hall that night?", "\"{V} and {D} argued over a $2,000 debt at a table, and then {V} was shot.\""), .direct("What does your hall camera show?", "\"{DL} and {V} arguing. It shows the confrontation but not every second of the shooting.\""), .direct("What did ballistics show?", "\"Casings match {D.his} pistol. A patron told me that {D.he} pulled first.\""), .direct("How did the argument start?", "\"{V} and {DL} were at a back table around ten. {V} raised the $2,000 {DL} owed, and {DL} said it would be paid when it was paid.\""), .direct("What did you see after that?", "\"{V} stood up, pushed back a chair, and {DL} pulled out a pistol and fired. I ducked behind the bar and called 911 within a minute.\""), .direct("What happened afterward?", "\"{D.He} stood there for a few seconds and then left. {V} was on the floor, and several patrons helped until medics arrived.\""), .cross("{D} says {V} drew first, doesn't {D.he}?", "\"Yes. {V}'s pistol had a round chambered, That much is true.\""), .cross("Did anyone else see {V} draw?", "\"A patron saw a gun on {V}. I did not see the draw myself.\""), .cross("Did the defendant owe {V} the money?", "\"Yes. {DL} owed the debt. That is what the argument was about.\""), .cross("Did you see {V} reach for a pistol?", "\"Not with my own eyes. A patron said {V} had a gun, and one was found near {V}'s body.\""), .cross("Did the defendant threaten {V} before the shot?", "\"I heard {DL} say 'Back off,' but I did not hear anything more serious.\"")],
        defenseRole: "Patron",
        defenseExam: [.direct("Did {V} have a gun that night?", "\"I saw one on {V}. It was in {V}'s hand at some point, I believe.\""), .direct("Did {V} draw it before the shot?", "\"I am unsure. It all happened fast, and I was looking at the table.\""), .direct("What did {D} do?", "\"{D} fired. It was quick, and I saw the flash before I understood.\""), .direct("How often are you at the pool hall?", "\"Several times a week. I know most of the regulars, including {DF} and {V}.\""), .direct("What did you see that night?", "\"I was at the next table. I heard them argue about money and saw {V} stand and reach for something near the waist.\""), .direct("What did you do when the shots started?", "\"I dropped to the floor and covered my head. I never saw who fired.\""), .cross("Did you see who drew first?", "\"No. I cannot say. I saw guns out, but not who pulled first.\""), .cross("Where were you standing?", "\"About fifteen feet away. I ducked right away.\""), .cross("Do you know the defendant?", "\"I have seen {DF} at the hall. I do not know {DF} well.\""), .cross("Did you see a gun in {V}'s hand?", "\"I saw one on the floor afterward. Before the shot, I saw the movement only.\""), .cross("Did the defendant pull first?", "\"I cannot say. It was too fast, and I was looking down at my game.\"")],
        theory: ("{D} shot {V}.", "Self-defense."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} owed the debt.", "{V}'s pistol had a round chambered."),
        defendant: [.direct("Did you fire first?", "\"No. {V} drew first, and I fired to protect myself. I did not start it.\""), .direct("Why did you fire?", "\"{V} pulled a gun during the argument over the debt. I was afraid, and I reacted.\""), .direct("Did you owe {V} the money?", "\"Yes. I owed $2,000. It was the reason we argued.\""), .direct("How did you come to borrow $2,000 from {V}?", "\"I needed to cover a bill and {V} offered. We agreed on a repayment date, and I paid part.\""), .direct("Why were you carrying a pistol?", "\"I carry for protection. I carry at night when I am near cash, and I had a permit.\""), .direct("Tell us what happened at the table.", "\"{V} stood and reached behind {V.his} back. I saw the pistol come out. I pulled mine and fired because I thought I would be shot.\""), .cross("{V}'s pistol had a round chambered, didn't it?", "\"Yes. That is what I saw. It was ready.\""), .cross("A patron says you pulled first. Is the patron wrong?", "\"I think the patron missed it. It happened fast.\""), .cross("You shot someone over a debt, didn't you?", "\"It was not over the debt. It was because a gun was drawn.\""), .cross("Your gun fired first, according to a patron. Why doesn't the patron's account count?", "\"The patron was across the room and saw only the end. It happened in a second.\""), .cross("You were in debt to {V} and in an argument. Isn't that a motive?", "\"It would be, if I had come to shoot {V}. I came to talk. I fired because a gun was out.\"")],
        openings: ("{V} was shot in a pool hall after an argument over a $2,000 debt. A camera shows {D} and {V} arguing, casings match {D}'s pistol, and a patron says {D} pulled first.", "The defense witnesses will explain that {V} drew a pistol with a round chambered and that {D} fired in fear. Who drew first is the whole case."),
        closings: ("A debt, an argument on camera, casings from {D}'s pistol, and a patron who says {D} pulled first. {V} died over $2,000.", "A loaded pistol in {V}'s hand and a split second to decide. The State must prove {D} was not defending, and who drew first is in real doubt."),
        timeline: [(0, "10 p.m.: the argument."), (0, "10:12 p.m.: shots."), (0, "10:15 p.m.: 911."), (0, "10:40 p.m.: arrest.")],
        identified: "A hall camera.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "He was my son.",
        doctrines: ["selfDefense"],
        genders: ["D": .male, "V": .male])

    static let houseDriveByShots = SmallCases.make(
        key: "story.houseDriveByShots",
        category: .violent,
        headlines: ["Drive-By Shots Hit Occupied House With Family Inside", "Bullets Lodge in Children's Room Wall"],
        law: "dischargingOccupied",
        threshold: 8,
        spec: "Willfully discharged a firearm into an occupied dwelling of {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Six shots hit a house on {DATE} with a family inside; one lodged in a children's room. {D}'s car was seen leaving. {DL} says the car was lent.",
        state: [E(.forensic, 3, "Casings", "Match a pistol found in {D}'s car."), E(.video, 2, "Street Camera", "A car leaves."), E(.physical, 3, "Pistol", "In {D}'s car.", .search)],
        defense: [E(.statement, 1, "Lent", "{DL} says the car was lent.")],
        role: "Homeowner",
        exam: [.direct("What happened at your house on {DATE}?", "\"At about 11 p.m. I was in the living room when six shots hit the front of the house. Glass broke, and we all dropped to the floor with the children screaming.\""), .direct("Where was your family when the shots hit?", "\"My spouse and I were in the front room, and the children were in two bedrooms along that wall. One bullet lodged in the wall of a children's room above a bed.\""), .direct("What did you do right after?", "\"I crawled to the children, checked each one, and called 911 at about 11:02. Deputies arrived a few minutes later and found the casings in the street.\""), .direct("What did deputies find in {D}'s car?", "\"A pistol under the front seat. A lab matched it to the casings found in front of my house. The car was stopped within the hour.\""), .direct("What does the street camera show?", "\"A car pulling away from my block right after the shots, with its lights on. It is a sedan, and the plate is hard to read in the footage.\""), .direct("What history is there between you and the defendant?", "\"We had a dispute over a parking and noise issue a few weeks earlier. It got heated, but I never imagined it would turn into this.\""), .cross("Did you see who fired the shots?", "\"No. I was inside and on the floor. I did not see a face or a car until deputies showed me the video.\""), .cross("Can you tell from the camera that the car is the defendant's?", "\"It looks like it, but the image is dark. I would not swear it is the same car without the plate.\""), .cross("Was anyone hurt?", "\"No. Nobody was hit, which is a miracle. The bullet in the children's room stopped a few feet from a bed.\""), .cross("Did the defendant threaten you directly before that night?", "\"Words were exchanged. I do not recall a direct threat to shoot at my home.\""), .cross("Do you know who was driving the car?", "\"No. I only know what deputies told me, that the car belongs to {D}.\"")],
        defenseRole: "Car's owner",
        defenseExam: [.direct("How long have you owned the car?", "\"About four years. It is a sedan I use for work, and I keep a spare key in a drawer for emergencies.\""), .direct("Do you lend it to others?", "\"Sometimes, to friends or neighbors who ask. I do not keep a record, and I do not always know where it goes.\""), .direct("Did you lend it to {D} on the night of the shooting?", "\"I believe I did, but I will be honest that it is hazy. I lend it out a lot, and that night I was tired.\""), .direct("What did you do when you heard about the shooting?", "\"I was shocked. I called {D} and asked what had happened. {D.He} said the car had been returned.\""), .direct("Did you keep any weapon in the car?", "\"No. I never carry a gun in the car. I do not own a pistol at all.\""), .direct("What kind of person is the defendant?", "\"Quiet most of the time. I have never seen {DF} act violently, and I would not expect it.\""), .cross("Who had the car that night?", "\"I cannot say for certain. Several people have used it, and I did not write anything down.\""), .cross("Did the defendant borrow it that night or some other night?", "\"I think that night, but I am not sure. My memory is unclear on the exact date.\""), .cross("Why can't you remember clearly?", "\"It was weeks ago, and I lend it out often. I did not know it would matter.\""), .cross("Did you see the defendant bring the car back?", "\"No. I found it in my driveway the next morning. I did not see who returned it.\""), .cross("Did you know there was a pistol in it?", "\"No. I looked under the seat only after deputies told me. It was not there when I last cleaned the car.\"")],
        theory: ("{D} fired into a home.", "A lent car."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had a dispute with {V}.", "The car owner confirms lending it that night."),
        defendant: [.direct("Whose car is that on the video?", "\"It is mine. I lent it that evening to someone who asked to use it. I was at home when the shooting happened.\""), .direct("Who did you lend it to?", "\"A person I know from the neighborhood. I believe I know who, but I did not see who drove away, and I do not want to accuse the wrong person.\""), .direct("Why was a pistol under the seat when deputies stopped the car?", "\"I do not know. It was not mine, and I never put it there. Whoever borrowed the car must have left it.\""), .direct("What was your dispute with {V}?", "\"A fight over noise and parking. I said a few angry things, but I let it go and did not plan anything.\""), .direct("What did you do when deputies stopped the car?", "\"I was not in it. The deputies found it parked near my house later. I told them it had been lent out and gave them all I knew.\""), .direct("How has this affected you?", "\"Terrible. Children were in that house. I would never fire at a home with kids inside, and I want whoever did it to be caught.\""), .cross("The pistol in your car matches the casings. Why shouldn't the jury conclude you fired?", "\"Because I was not in the car. The pistol may have come from the borrower, and I did not know it was there.\""), .cross("You cannot name the borrower. Isn't that convenient?", "\"It is not convenient for me. I am not sure who it was, and I will not point at someone without being certain.\""), .cross("The car left the scene near your home. Doesn't that suggest you?", "\"It suggests the car, not me. I was inside my house when the shots were fired.\""), .cross("You had a recent dispute with {V}. Isn't that motive?", "\"I was angry weeks ago. It was not enough to shoot at a house, and I did not do it.\""), .cross("Did anyone see you at home that night?", "\"No one but me. I live alone, and I know that is a weakness.\"")],
        openings: ("Six shots hit a house with a family inside, one lodging in a children's room. A car was seen leaving, and a matching pistol was in {D}'s car. The State will present the homeowner and the casings.", "Jurors will also see a car that was lent out, an owner who cannot say to whom, and no one who saw who fired. Listen closely to the witnesses."),
        closings: ("Six shots into a house with children asleep inside, a car leaving the block, and a pistol in {D}'s car that matches every casing. Those facts lead to the person who owned the car.", "A car that was lent out, an owner who cannot be sure who drove it, and not one witness who saw the shooter. The State cannot say {D} fired any of those shots, and doubt is reasonable."),
        timeline: [(-3, "The dispute."), (0, "11 p.m.: the shots."), (0, "11:02 p.m.: the car."), (1, "The stop.")],
        identified: "Casings and a pistol.",
        aggravating: ["The offense involved a firearm", "The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "My kids still sleep in our room.",
        doctrines: ["searchSeizure"])

    static let backpackGunSchool = SmallCases.make(
