        defense: [E(.statement, 1, "Cousin", "{DL} says a cousin left it.")],
        role: "Assistant principal",
        exam: [.direct("How did you learn about the pistol on {DATE}?", "\"At about 9 a.m. a classmate came to a teacher and said they had seen a gun in {D}'s backpack. The teacher walked the student straight to my office.\""), .direct("What did the classmate say?", "\"The student said they saw the pistol when the bag was open between classes, and that it looked real. The student was nervous but clear.\""), .direct("What did you do next?", "\"I called deputies, closed off the hallway, and had staff watch the locker area. At about 9:15 we opened the locker with the combination on file.\""), .direct("What did you find in the locker?", "\"A loaded pistol inside a backpack. The magazine was in, and a round was chambered. Deputies took it safely.\""), .direct("What does the hall camera show?", "\"It shows {DL} arriving at about 7:50 with a backpack and carrying it to the locker. The same backpack appears on camera when staff opened the locker.\""), .direct("What happened to {D}?", "\"Deputies took {D.him} out of class at about 10 and questioned {D.him} in my office. The school suspended {D.him} on the spot.\""), .cross("Did you see the pistol in the defendant's hands?", "\"No. I saw the pistol in the locker and the backpack on the camera. I did not see {DL} touch the gun.\""), .cross("Who else knew the locker combination?", "\"The school office has it, and students often share them. I cannot rule out that others could open it.\""), .cross("Was the locker assigned to the defendant?", "\"Yes, the locker was assigned to {D.him}. That is why we opened it.\""), .cross("Did the defendant say anything when questioned?", "\"{D.He} said a cousin had left it and that {D.he} did not know it was in the bag. {D.He} seemed shaken.\""), .cross("Did you speak with the cousin?", "\"Not at the time. A deputy spoke with a relative later that day.\"")],
        defenseRole: "Cousin",
        defenseExam: [.direct("Why were you at {D}'s school that day?", "\"I came for an after-school game. I arrived in the morning to help set up and walked through the building.\""), .direct("How are you related to the defendant?", "\"We are cousins. We grew up together and spend a lot of time at each other's houses.\""), .direct("Did you see the defendant that morning?", "\"Yes. I saw {D} in the hall and said hello. {D.He} had the backpack on a shoulder.\""), .direct("What do you know about the gun?", "\"Only what I was told after. I never touched it and did not put anything in anyone's bag.\""), .direct("How would you describe the defendant?", "\"Easygoing and a little shy. {D.He} has never been in a fight that I know of.\""), .direct("What did the defendant say to you after?", "\"That deputies thought the gun was {DF}'s. {DF} was frightened and said it had nothing to do with {D.him}.\""), .cross("Did you leave a gun in the locker?", "\"No. I did not. I have never carried a gun to school.\""), .cross("Were you near the locker at any point?", "\"Not that I can recall. I spent most of the morning in the gym.\""), .cross("Do you own a pistol?", "\"No. I do not. I would not know where to get one.\""), .cross("Why would {D} say it was yours?", "\"I do not understand it. I told deputies the same thing I am telling you.\""), .cross("Did you look inside the defendant's bag?", "\"No. I did not touch it. I only saw it on {D.his} shoulder.\"")],
        theory: ("{D} brought a gun to school.", "A cousin."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had carried the backpack that morning.", "The cousin was on campus for a game."),
